var sb = new System.Text.StringBuilder(); var d = document;
foreach (var tb in new FilteredElementCollector(d).OfCategory(BuiltInCategory.OST_TitleBlocks).WhereElementIsElementType().Cast<FamilySymbol>()) sb.AppendLine("TB " + tb.FamilyName + " | " + tb.Name + " w " + Math.Round((tb.get_Parameter(BuiltInParameter.SHEET_WIDTH)?.AsDouble() ?? 0)*304.8) + " h " + Math.Round((tb.get_Parameter(BuiltInParameter.SHEET_HEIGHT)?.AsDouble() ?? 0)*304.8));
foreach (var vft in new FilteredElementCollector(d).OfClass(typeof(ViewFamilyType)).Cast<ViewFamilyType>()) if (vft.ViewFamily == ViewFamily.Section || vft.ViewFamily == ViewFamily.Detail || vft.ViewFamily == ViewFamily.ThreeDimensional) sb.AppendLine("VFT " + vft.ViewFamily + " | " + vft.Name + " tag " + d.GetElement(vft.get_Parameter(BuiltInParameter.SECTION_TAG)?.AsElementId() ?? ElementId.InvalidElementId)?.Name);
foreach (var vp in new FilteredElementCollector(d).OfClass(typeof(ElementType)).Cast<ElementType>().Where(x => x.FamilyName == "Видовой экран" || x.FamilyName == "Viewport")) sb.AppendLine("VPT " + vp.Name + " title " + d.GetElement(vp.get_Parameter(BuiltInParameter.VIEWPORT_ATTR_LABEL_TAG)?.AsElementId() ?? ElementId.InvalidElementId)?.Name);
foreach (var st in new FilteredElementCollector(d).OfCategory(BuiltInCategory.OST_SectionHeads).WhereElementIsElementType().Cast<ElementType>()) sb.AppendLine("SECHEAD " + st.FamilyName + " | " + st.Name);
foreach (var st in new FilteredElementCollector(d).OfClass(typeof(ElementType)).Cast<ElementType>().Where(x => x.FamilyName.Contains("Марка разреза") || x.FamilyName.Contains("Section Tag"))) sb.AppendLine("SECTAG " + st.FamilyName + " | " + st.Name);
foreach (var gs in new FilteredElementCollector(d).OfCategory(BuiltInCategory.OST_GenericAnnotation).WhereElementIsElementType().Cast<FamilySymbol>()) sb.AppendLine("GA " + gs.FamilyName + " | " + gs.Name);
foreach (var v in new FilteredElementCollector(d).OfClass(typeof(View)).Cast<View>().Where(x => x.IsTemplate)) sb.AppendLine("TMPL " + v.ViewType + " | " + v.Name);
foreach (var v in new FilteredElementCollector(d).OfClass(typeof(View)).Cast<View>().Where(x => !x.IsTemplate && (x.ViewType == ViewType.Section || x.ViewType == ViewType.ThreeD))) sb.AppendLine("VIEW " + v.ViewType + " | " + v.Name);
var lp = new FilteredElementCollector(d).OfClass(typeof(LinePatternElement)).Cast<LinePatternElement>().Select(x => x.Name); sb.AppendLine("LPAT " + string.Join(", ", lp));
foreach (var gst in new FilteredElementCollector(d).OfClass(typeof(GraphicsStyle)).Cast<GraphicsStyle>().Where(x => x.GraphicsStyleCategory?.Parent?.Id.Value == (long)BuiltInCategory.OST_Lines)) sb.AppendLine("LS " + gst.Name);
var fp = new FilteredElementCollector(d).OfClass(typeof(FillPatternElement)).Cast<FillPatternElement>().Where(x => x.GetFillPattern().IsSolidFill).Select(x => x.Name + "#" + x.Id); sb.AppendLine("SOLID " + string.Join(", ", fp));
return sb.ToString();
